css:
.stage{position:absolute;inset:0}
.scrim-top{position:absolute;left:0;right:0;top:0;height:820px;background:linear-gradient(180deg,rgba(14,11,8,.72) 0%,rgba(14,11,8,.45) 55%,rgba(14,11,8,0) 100%)}

.hook{position:absolute;left:72px;right:72px;top:186px;text-align:center}
.kicker{display:inline-block;padding:13px 30px;border-radius:100px;background:#C7523B;color:#FFF3E8;font-size:32px;letter-spacing:.18em;text-transform:uppercase;font-weight:600;margin-bottom:30px}
.hook h1{font-size:100px;line-height:1.03;color:#FFF6EC;font-weight:700;letter-spacing:-.025em;text-shadow:0 12px 44px rgba(0,0,0,.6)}
.hook h1 em{font-style:normal;color:#E8A33D}

.card{position:absolute;left:66px;right:66px;top:268px;background:rgba(20,16,12,.88);border-radius:36px;padding:46px 48px;border-left:9px solid #E8A33D;box-shadow:0 26px 70px rgba(0,0,0,.42)}
.card .num{font-size:29px;color:#E8A33D;letter-spacing:.22em;font-weight:600;margin-bottom:16px;text-transform:uppercase}
.card p{font-size:58px;line-height:1.16;color:#FFF6EC;font-weight:600}
.card .sub{font-size:36px;line-height:1.3;color:#CDBBA5;font-weight:400;margin-top:18px}
.strike{position:relative;color:#C7523B}
.strike:after{content:'';position:absolute;left:-6px;right:-6px;top:52%;height:7px;background:#C7523B;transform:rotate(-3deg);border-radius:4px}

.split{position:absolute;left:66px;right:66px;top:290px;display:flex;gap:22px}
.col{flex:1;background:rgba(20,16,12,.88);border-radius:32px;padding:38px 34px;box-shadow:0 26px 70px rgba(0,0,0,.42)}
.col.dim{opacity:0}
.col h3{font-size:28px;letter-spacing:.16em;text-transform:uppercase;font-weight:600;margin-bottom:22px}
.col.a h3{color:#8FA9B8}
.col.b h3{color:#E8A33D}
.col li{font-size:44px;line-height:1.22;color:#FFF6EC;font-weight:600;list-style:none;margin-bottom:14px}
.col .arrow{margin-top:20px;font-size:34px;color:#E8A33D;font-weight:600}

.list{position:absolute;left:66px;right:66px;top:290px;background:rgba(20,16,12,.88);border-radius:36px;padding:44px 46px;box-shadow:0 26px 70px rgba(0,0,0,.42)}
.list .num{font-size:29px;color:#E8A33D;letter-spacing:.22em;font-weight:600;margin-bottom:26px;text-transform:uppercase}
.list .row{display:flex;align-items:flex-start;gap:20px;margin-bottom:20px}
.list .dot{width:14px;height:14px;border-radius:50%;background:#E8A33D;margin-top:20px;flex:none}
.list .row span{font-size:50px;line-height:1.18;color:#FFF6EC;font-weight:600}
.list .row.off{opacity:0}
.list .row.hi span{color:#E8A33D}
.list .row.hi .dot{background:#C7523B;width:18px;height:18px;margin-top:18px}

.quote{position:absolute;left:66px;right:66px;top:250px;text-align:center}
.quote .mark{font-size:150px;line-height:.7;color:#E8A33D;font-weight:700;margin-bottom:14px}
.quote p{font-size:82px;line-height:1.1;color:#FFF6EC;font-weight:700;letter-spacing:-.02em;text-shadow:0 14px 48px rgba(0,0,0,.72)}
.quote .tag{margin-top:30px;display:inline-block;padding:12px 28px;border-radius:100px;background:rgba(199,82,59,.92);color:#FFF3E8;font-size:30px;letter-spacing:.14em;text-transform:uppercase;font-weight:600}

.big{position:absolute;left:66px;right:66px;top:280px;text-align:center}
.big .n{font-size:230px;line-height:.92;color:#E8A33D;font-weight:700;letter-spacing:-.04em;text-shadow:0 16px 50px rgba(0,0,0,.6)}
.big .cap{margin-top:14px;font-size:48px;color:#FFF6EC;font-weight:600;text-shadow:0 10px 34px rgba(0,0,0,.6)}

.cta{position:absolute;left:66px;right:66px;top:300px;background:rgba(20,16,12,.9);border-radius:36px;padding:42px 46px;display:flex;align-items:center;gap:26px;box-shadow:0 26px 70px rgba(0,0,0,.45)}
.cta .ico{width:96px;height:96px;border-radius:26px;background:#E8A33D;color:#1A1310;font-size:52px;font-weight:700;display:flex;align-items:center;justify-content:center;flex:none}
.cta .t1{font-size:50px;color:#FFF6EC;font-weight:700;line-height:1.12}
.cta .t2{font-size:33px;color:#CDBBA5;font-weight:400;margin-top:8px}
